def getPalmRegionEdge(binary):

    assert binary is not None
    assert np.issubdtype(binary.dtype, np.integer)

    # kernel = np.ones((3, 3), np.uint8)
    # binary = cv2.dilate(binary, kernel, iterations=1)
   
    version = (cv2.__version__).split('.')[0]
    if version == '3':
        _, contours, _ = cv2.findContours(binary, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE) #cv2.findContours(binary, cv2.RETR_LIST, cv2.CHAIN_APPROX_SIMPLE) # simple 
    elif version == '4':
        contours, _ = cv2.findContours(binary, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE) 
    else:
        raise AssertionError('getPalmRegion: opencv version should >= 3 !')

  

    assert contours is not None and len(contours) != 0

    if len(contours) > 1:
        id = np.argmax([cv2.contourArea(cnt) for cnt in contours])
    else:
        id = 0
    cnt = contours[id]

    r,c = binary.shape

    palmregion = np.zeros((r,c), dtype=np.uint8)
    cv2.drawContours(palmregion, contours, id, (255,255,255), 5)           

    return palmregion, np.array(cnt)


def getDislist(contour, refpt):
    """
    inputs
    contour: [id, 0, [x, y]]
    imshape: shape of the palm image
    output
    dist: python list
    """
    assert contour is not None and refpt is not None
       
    x = refpt[0]
    y = refpt[1]
    # print(contour.shape)
    num,_ ,_ = contour.shape
    dist = []
    for i in range(num):
        # pt(x,y)
        pt = (contour[i, 0, 0], contour[i, 0, 1]) 
        dx = x - pt[0]
        dy = y - pt[1]
        distance = dx*dx + dy*dy # caution: big number
        dist.append(distance)

    return np.array(dist)


def getFingerValleyPoints(contour, kps):
    assert contour is not None and kps is not None
    # print(contour.shape, kps)
    assert len(kps) == 4 and contour.shape[0] > 50

    x1, y1 = kps[:2]
    x2, y2 = kps[2:]

    
    dist1 = getDislist(contour, (x1, y1))
    # minidx = np.argmin(dist1)
    # minv = np.min(dist1)
    # print('pt1', minv, minidx)
    dist2 = getDislist(contour, (x2, y2))
    # minidx = np.argmin(dist2)
    # minv = np.min(dist2)
    # print('pt2', minv, minidx)
    id1 = np.argmin(dist1)
    id2 = np.argmin(dist2)

    N = len(contour)

    SIDE_LEN = 20
    # SIDE_LEN = 50 ###############################################################

    if id1-SIDE_LEN < 0:
        id1_low = N + id1-SIDE_LEN
    else:
        id1_low = id1-SIDE_LEN
    if id1+SIDE_LEN > N-1:
        id1_high = id1+SIDE_LEN-N
    else:
        id1_high = id1+SIDE_LEN

    if id2-SIDE_LEN < 0:
        id2_low = N + id2-SIDE_LEN
    else:
        id2_low = id2-SIDE_LEN
    if id2+SIDE_LEN > N-1:
        id2_high = id2+SIDE_LEN-N
    else:
        id2_high = id2+SIDE_LEN

    vps1 = contour[id1_low:id1_high+1, 0, :]
    vps2 = contour[id2_low:id2_high+1, 0, :]
    return [vps1, vps2]



class DefaultLoader(data.Dataset):
    def __init__(self, root_dir, aug_transform=None, dataset=None,
                 img_transform=None, label_transform=None, keypoint_transform=None): 

        self.aug_transform = aug_transform

        self.img_transform = img_transform
        self.label_transform = label_transform
        self.keypoint_transform = keypoint_transform

        self.img_list, self.label_list, self.keypoint_list, self.background_list, self.name_list = self.__list_dirs(root_dir, dataset)

        size_mode = "fix_size" if dataset == 'train' else 'diverse_size'

        self.is_stack = size_mode != 'diverse_size'

        np.random.seed(1)

        # self.label_list = []

    def __len__(self):
        return len(self.img_list)

    def __getitem__(self, index):
        # palm image
        img = ImageHelper.read_image(self.img_list[index], tool='cv2', mode='BGR')

        h, w = img.shape[0], img.shape[1]

        if w > h:
            transFlag = True
        else:
            transFlag = False

        # segment label image
        labelmap = ImageHelper.read_image(self.label_list[index], tool='cv2', mode='P')
 
        img = cv2.resize(img, (labelmap.shape[1], labelmap.shape[0]))###################################<-----


        if transFlag:
            img = cv2.rotate(img, 0)
            labelmap = cv2.rotate(labelmap, 0)

        img_size = ImageHelper.get_size(img)

        # prepare background
        if random.random() > 0.2:    
            a = random.random()
            if a <= 0.7:
                idx = int(np.random.rand(1)*len(self.background_list))# print(idx, self.background_list[idx])
                bgimg = cv2.imread(self.background_list[idx])   # VOC image
            elif a > 0.7 and a <=0.75:
                bgimg = np.ones((3,3,3))*255                    # white
            elif a > 0.75 and a <= 0.8:
                bgimg = np.ones((3,3,3))*255*np.random.rand(1)  # gray
            elif a > 0.8 and a <= 0.85:
                bgimg = np.ones((3,3,3))*np.random.rand(1,1,3)*255*np.random.rand(1) # uni-color
            elif a > 0.85 and a <= 0.875:
                bgimg = np.random.rand(3,3,3)*255               # color
            elif a> 0.875 and a <= 0.9:
                bgimg = np.random.rand(16,12,3)*255             # color
            else: 
                bgimg = (np.ones((3,3,3))*255)                    # warm color
                bgimg[:,:,0] = np.random.rand(1)*(60.0/360)*180   # H
                bgimg[:,:,1] = np.random.rand(1)*100              # S
                bgimg[:,:,2] = np.random.rand(1)*50+125           # V
                bgimg = cv2.cvtColor(bgimg.astype(np.uint8), cv2.COLOR_HSV2BGR)
                  

            bgimg = bgimg.astype(np.uint8)            
            bgimg = cv2.resize(bgimg, (labelmap.shape[1], labelmap.shape[0])) # cv2.imshow('bg', bgimg)

            # mask 
            msk = labelmap//255                         # 0, 1    
            msk = np.stack((msk, msk, msk), axis=2)

            edge_blur_ratio = random.random()
            pmsk = copy.deepcopy(msk)            
            if edge_blur_ratio > 0.8 and edge_blur_ratio <= 0.95:
                pmsk = cv2.GaussianBlur(pmsk, (3, 3), 0)
            elif edge_blur_ratio > 0.95:
                pmsk = cv2.GaussianBlur(pmsk, (5, 5), 0)

            # extract palm
            img = (img*pmsk).astype(np.uint8)
        

            # prepare ambient light
            if random.random() > 0.95:#0.85:
                b = np.random.rand(1)
                if b <= 0.2:
                    light = np.zeros((3,3,1))
                elif b > 0.2 and b <= 0.3:
                    light = np.random.rand(3,3,1)*80
                elif b > 0.3 and b <= 0.4:
                    light = np.random.rand(5,5,1)*80
                elif b > 0.4 and b <= 0.5:
                    light = np.random.rand(7,7,1)*80
                elif b > 0.5 and b <= 0.6:
                    light = np.random.rand(9,9,1)*80
                elif b > 0.6 and b <= 0.7:
                    light = np.random.rand(11,11,1)*80
                elif b > 0.7 and b <= 0.8:
                    light = np.random.rand(13,13,1)*80
                elif b > 0.8 and b <= 0.9:
                    light = np.random.rand(15,15,1)*80
                else:
                    light = np.random.rand(19,19,1)*80

                light = light.astype(np.uint8)      
                light = cv2.resize(light, (img.shape[1], img.shape[0]))

                img = cv2.cvtColor(img, cv2.COLOR_BGR2HSV)

                imgv = (img[:,:,2]).astype(np.int32)

                if np.random.rand(1) >= 0.5:
                    flag = 1
                else:
                    flag = -1

                # print(imgv.dtype, light.dtype)
                imgv += flag * light

                # img = (img-img.min())/(img.max()-img.min()+1e-6)*255
                imgv[imgv>255] = 255
                imgv[imgv<0] = 0
                imgv = imgv.astype(np.uint8) 
                img[:,:,2] = imgv
                img = cv2.cvtColor(img, cv2.COLOR_HSV2BGR)


            # extract palm again
            img = img*pmsk
                
            # invert mask
            msk[msk==0] = 128
            msk[msk==1] = 0
            msk[msk==128] = 1

            # extract bg
            bgimg= bgimg*msk
            bgimg = bgimg.astype(np.uint8)


            # synthesize
            img += bgimg
            img = img.astype(np.uint8)
   

        
        # remove color
        if random.random()> 0.9: 
            img = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) 
            img = cv2.cvtColor(img, cv2.COLOR_GRAY2BGR)

        # add blur
        if random.random()> 0.8:
            a = int(random.random()*17)
            if a%2==0:
                img = cv2.GaussianBlur(img, (3+a, 3+a), 0)
            else:
                img = cv2.GaussianBlur(img, (3+a+1, 3+a+1), 0)


        # kernel = np.ones((3, 3), np.uint8)
        # labelmap = cv2.dilate(labelmap, kernel, iterations=3)

        # load keypoint coordinates
        kpinfo = np.loadtxt(self.keypoint_list[index])  # 1 rotation(degree), 1 tangent lenght, 2 finger valley kps, 4 roi kps

        uid = int(os.path.basename(self.img_list[index])[:4]) # bigDB, left right hand flag#################<---

        if uid>0 and uid<=600:
            if uid % 2 == 0:
                thumbUp = 1
            else:
                thumbUp = 0
        elif uid>=601 and uid<=1060:
            thumbUp = 1
        elif uid>=1061 and uid<=1223:
            thumbUp = 1
        elif uid>=1224 and uid<=1847:
            if uid % 2 == 0:
                thumbUp = 0
            else:
                thumbUp = 1
        elif uid>=1848 and uid<=2205:
            if (uid-1848+1) <= 179:
                thumbUp = 0
            else:
                thumbUp = 1
        # thumbUp = 1

        # reorder kp
        if thumbUp == 1:
            kps = kpinfo[2:]
        else:
            kps = [kpinfo[4], kpinfo[5], kpinfo[2], kpinfo[3], kpinfo[8], kpinfo[9], kpinfo[6], kpinfo[7], kpinfo[12], kpinfo[13], kpinfo[10], kpinfo[11]]

        kps = np.array(kps)

        # rotate kp
        if transFlag:
            x = kps[:-1:2].copy()
            y = kps[1::2].copy()           
        
            X = img.shape[1]-y
            Y = x
           
            kps[:-1:2] = X
            kps[1::2] = Y

            # print(x,y,X,Y,kps)

        ## visuale the loaded keypoints
        # kp = kps.numpy().astype(np.int)
        # c1 = (kp[0], kp[1])
        # c2 = (kp[2], kp[3])
        # r1 = (kp[4], kp[5])
        # r2 = (kp[6], kp[7])
        # r3 = (kp[8], kp[9])
        # r4 = (kp[10], kp[11])

        # cv2.circle(img, c1, radius=5, thickness=3, color=(0,0,255))
        # cv2.circle(img, c2, radius=5, thickness=3, color=(0,255,0))

        # cv2.circle(img, r1, radius=5, thickness=3, color=(255,0,0))
        # cv2.circle(img, r2, radius=5, thickness=3, color=(0,0,0))
        # cv2.circle(img, r3, radius=5, thickness=3, color=(0,255,255))
        # cv2.circle(img, r4, radius=5, thickness=3, color=(255,255,0))

        # cv2.imshow("img", img)
        # cv2.waitKey(0)

        # obtain palm edge image and palm contour coordinates
        edge, contour = getPalmRegionEdge(labelmap)
        # cv2.imshow("edge", edge)
        # cv2.waitKey(0)

        # obtain the two finger valleys 
        vps = getFingerValleyPoints(contour, kps[:4]) # (fv id, kp id, xy id)
        vp1, vp2 = vps
       
        kps = np.concatenate((kps, vp1.reshape(-1), vp2.reshape(-1)), axis=0) # xyxyxyxyxyxyxyxy... (fv kp, roi kp, fv)

        # print(kps)

        ## visualize the loaded finger valleys
        # colors = [(0,0,255), (0,255,0)]
        # for i in range(2):
        #     xlist = vps[i][:, 0]
        #     ylist = vps[i][:, 1]
        #     for k in range(len(xlist)):
        #         cv2.circle(img, (xlist[k], ylist[k]), radius=1, thickness=1, color=colors[i])
        # cv2.imshow("img", img)
        # cv2.waitKey(0)

        # labelmap
        ori_target = ImageHelper.tonp(labelmap) 
        # ori_target[ori_target == 255] = -1  # regions with -1 will be ignored
        # print(labelmap.min(), labelmap.max())
        
        labelmap[labelmap==0]=0
        labelmap[labelmap==255]=1
        labelmap[edge==255]=2

        
        if self.aug_transform is not None:
            img, labelmap, kps = self.aug_transform(img, labelmap=labelmap, keypoint=kps)
          
    
        # cv2.imshow('img', img)
        # cv2.imshow('labelmap', labelmap.astype(np.uint8))
        # cv2.waitKey(0)


        border_size = ImageHelper.get_size(img)

        if self.img_transform is not None:
            img = self.img_transform(img)

        if self.label_transform is not None:
            labelmap = self.label_transform(labelmap)
            # print(labelmap.min(), labelmap.max())#############


        kps = torch.Tensor(kps)
        # if self.keypoint_transform is not None:
        #     kps = self.keypoint_transform(kps)# inputs = torch.from_numpy(inputs.transpose(2, 0, 1)) ValueError: axes don't match array    
                 
            


        meta = dict(
            ori_img_size=img_size,
            border_size=border_size,
            ori_target=ori_target
        )
        return dict(
            img=DataContainer(img, stack=self.is_stack),
            labelmap=DataContainer(labelmap, stack=self.is_stack),
            keypoint=DataContainer(kps, stack=self.is_stack),
            meta=DataContainer(meta, stack=False, cpu_only=True),
            name=DataContainer(self.name_list[index], stack=False, cpu_only=True),
        )

    def _reduce_zero_label(self, labelmap):
        labelmap = np.array(labelmap)
        encoded_labelmap = labelmap - 1   
        return encoded_labelmap

    def _encode_label(self, labelmap):
        labelmap = np.array(labelmap)

        shape = labelmap.shape
        encoded_labelmap = np.ones(shape=(shape[0], shape[1]), dtype=np.float32) * 255
        for i in range(len(self.label_list)):
            class_id = self.label_list[i]
            encoded_labelmap[labelmap == class_id] = i        

        return encoded_labelmap


    def __list_dirs(self, root_dir, dataset):
        img_list = list()
        label_list = list()
        keypoint_list = list()
        background_list = list()
        name_list = list()

        image_dir = os.path.join(root_dir, dataset, 'image')
        label_dir = os.path.join(root_dir, dataset, 'label')
        keypoint_dir = os.path.join(root_dir, dataset, 'keypoint')
        background_dir = os.path.join(root_dir, 'background')


        
        imgfiles = sorted(os.listdir(image_dir))
        img_extension_dict = dict([['.'.join(n.split('.')[:-1]), n.split('.')[-1]] for n in imgfiles]) # img_extension = os.listdir(image_dir)[0].split('.')[-1]


        # support the argument to pass the file list used for training/testing
        file_list_txt = os.environ.get('use_file_list')
        if file_list_txt is None:
            files = sorted(os.listdir(label_dir))
        else:
            Log.info("Using file list {} for training".format(file_list_txt))
            with open(os.path.join(root_dir, dataset, 'file_list', file_list_txt)) as f:
                files = [x.strip() for x in f]

        for file_name in files:
            image_name = '.'.join(file_name.split('.')[:-1])

            img_path = os.path.join(image_dir, '{}.{}'.format(image_name, img_extension_dict[image_name]))
            label_path = os.path.join(label_dir, file_name)
            keypoint_path = os.path.join(keypoint_dir, '{}.{}'.format(image_name, 'txt'))

            # print(img_path, label_path, keypoint_path)

            if not os.path.exists(label_path) or not os.path.exists(img_path) or not os.path.exists(keypoint_path): #########
                Log.error('Path pair not exists: {}'.format(label_path))
                continue

            img_list.append(img_path)
            label_list.append(label_path)
            keypoint_list.append(keypoint_path)
            name_list.append(image_name)

        # print(label_path)
        # print(label_list)
        # print(len(label_list))

        for name in os.listdir(background_dir):
            background_list.append(os.path.join(background_dir, name))
        
        return img_list, label_list, keypoint_list, background_list, name_list



